<?php require_once __DIR__.'/includes/bootstrap.php';require_verified();$u=current_user();$staff=in_array($u['role'],['admin','librarian'],true);$status=$_GET['status']??'';$q=trim($_GET['q']??'');$sql="SELECT r.*,b.title,b.author,u.full_name member_name,(SELECT COUNT(*) FROM reservations earlier WHERE earlier.book_id=r.book_id AND earlier.id<r.id AND earlier.status IN('pending','approved','ready'))+1 queue_position FROM reservations r JOIN books b ON b.id=r.book_id JOIN users u ON u.id=r.user_id WHERE 1=1";$types='';$p=[];if(!$staff){$sql.=' AND r.user_id=?';$types.='i';$p[]=(int)$u['id'];}if(in_array($status,['pending','approved','ready','fulfilled','cancelled','rejected','expired'],true)){$sql.=' AND r.status=?';$types.='s';$p[]=$status;}if($q!==''){$sql.=' AND (b.title LIKE ? OR u.full_name LIKE ?)';$like="%$q%";$types.='ss';$p[]=$like;$p[]=$like;}$sql.=' ORDER BY r.id DESC';$s=$conn->prepare($sql);if($types)$s->bind_param($types,...$p);$s->execute();$rows=$s->get_result();page_header('Reservations');?><div class="page-heading"><div><p class="eyebrow">BOOK RESERVATION QUEUE</p><h1>Reservations</h1><p class="muted">Reserve a book even when all copies are currently borrowed.</p></div><a class="btn secondary" href="books.php">Browse books</a></div><form class="filter-bar"><input name="q" value="<?=e($q)?>" placeholder="Search book or member"><select name="status"><option value="">All statuses</option><?php foreach(['pending','approved','ready','fulfilled','cancelled','rejected','expired'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=ucfirst($x==='ready'?'Ready for pickup':$x)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="table-wrap panel"><table><thead><tr><th>ID</th><th>Member</th><th>Book</th><th>Queue</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['member_name'])?></td><td><strong><?=e($r['title'])?></strong><div class="muted small"><?=e($r['author'])?></div></td><td><?=in_array($r['status'],['pending','approved','ready'],true)?'#'.(int)$r['queue_position']:'—'?></td><td><?=e($r['requested_at'])?></td><td><?=status_badge($r['status']==='ready'?'ready':$r['status'])?></td><td><?php if($staff):?><form method="post" action="actions/reservation_transition.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="action" required><option value="">Choose</option><?php if($r['status']==='pending'):?><option value="approve">Approve</option><option value="reject">Reject</option><?php endif;?><?php if($r['status']==='approved'):?><option value="ready">Mark ready for pickup</option><?php endif;?><?php if($r['status']==='ready'):?><option value="complete">Complete pickup / issue book</option><option value="expire">Expire / no-show (release copy)</option><?php endif;?></select><button class="btn small-btn">Apply</button></form><?php elseif((int)$r['user_id']===(int)$u['id']&&in_array($r['status'],['pending','approved'],true)):?><form method="post" action="actions/reservation_cancel.php" data-confirm="Cancel this reservation?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small-btn">Cancel</button></form><?php else:?><span class="muted small">—</span><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7" class="empty">No reservations found.</td></tr><?php endif;?></tbody></table></div><?php page_footer();?>
